      "topologie": {
        "typ": "any",
        "pflicht": true
      },
      "params": {
        "typ": "object",
        "pflicht": true
      },
      "eta_max": {
        "typ": "number",
        "pflicht": true
      },
      "sigma_max": {
        "typ": "number",
        "pflicht": false
      },
      "v_min": {
        "typ": "number",
        "pflicht": false
      }
    },
    "untere_schranke": {
      "topologie": {
        "typ": "any",
        "pflicht": true
      },
      "c": {
        "typ": "any",
        "pflicht": false
      },
      "k": {
