    "optimum": {
      "topologie": {
        "typ": "any",
        "pflicht": true
      },
      "eta_min": {
        "typ": "number",
        "pflicht": true
      },
      "sigma_max": {
        "typ": "number",
        "pflicht": false
      },
      "v_min": {
        "typ": "number",
        "pflicht": false
      },
      "fest": {
        "typ": "object",
        "pflicht": false
      }
    },
    "erreichbar_liste": {
      "faelle": {
        "typ": "array",
        "pflicht": true
      }
    },
    "schranke_familie": {
      "familie": {
        "typ": "string",
        "pflicht": true
      },
      "ausdruck": {
        "typ": "string",
        "pflicht": true
      },
      "mitglieder": {
        "typ": "array",
        "pflicht": false
      }
    }
  },
  "regeln": "Rules: (1) Only submit_claim can confirm a result; it calls the domain's code verifier. (2) Tolerances belong to the verifier: tolerance fields in a claim are removed and reported. (3) Unknown fields are rejected. (4) Every call is logged to record.jsonl. (5) A rejected claim is a result too: report it openly. (6) Every number in a write-up must come from a confirmed claim. Tolerance fields are ignored: accuracy, atol, genauigkeit, precision, rtol, tol, tolerance, toleranz",
  "parameter": {
    "Delta": [
      "ln 100 (e^Delta = 100, e^-Delta = 0.01)",
      "discrimination free-energy difference in kT: W leaves bound states e^Delta times faster"
    ],
    "L": [
      "10",
      "range of log-rates: every rate, including derived reverse rates, lies in [e^-10, e^10]"
    ],
    "mu": [
      ">= 0, explored in [0, 20]",
      "fuel chemical potential (kT) consumed per fuel-driven step"
    ],
    "mu_P": [
      ">= 0, explored in [0, 20]",
      "chemical potential (kT) of product formation"
    ],
    "max_states": [
      "10",
      "maximal number of states of a network (unbound states plus R and W copies of bound states)"
    ],
    "concentrations": [
      "1",
      "substrate concentrations are absorbed into the binding rates (normalised)"
    ],
    "rationalisation": [
      "denominator <= 10^6",
      "rates are rounded to rationals with denominator at most 10^6 for exact certificates"
    ],
    "family_k": [
      "2",
      "number of bound states in the enumerated topology family (88 non-degenerate members)"
    ]
  }
}

